describe('Checkout Form Validation - Required Fields', () => {
  beforeEach(() => {
    cy.visit('https://www.saucedemo.com');
    cy.login('standard_user', 'secret_sauce');
  });

  it('should display error when only firstName is filled and lastName is empty', () => {
    cy.get('[data-testid="add-to-cart-sauce-labs-backpack"]').click();
    cy.get('[data-testid="shopping_cart_link"]').click();
    cy.get('[data-testid="checkout"]').click();

    cy.get('[data-testid="firstName"]').type('Saif');
    cy.get('[data-testid="lastName"]').should('be.visible');
    cy.get('[data-testid="lastName"]').type('');

    cy.get('[data-testid="continue"]').click();

    cy.get('[data-testid="error"]').should('be.visible');
    cy.get('[data-testid="error"]').should('contain', 'Postal Code is required');
  });

  it('should display error when only lastName is filled and firstName is empty', () => {
    cy.get('[data-testid="add-to-cart-sauce-labs-backpack"]').click();
    cy.get('[data-testid="shopping_cart_link"]').click();
    cy.get('[data-testid="checkout"]').click();

    cy.get('[data-testid="lastName"]').type('Afzal');
    cy.get('[data-testid="firstName"]').should('be.visible');
    cy.get('[data-testid="firstName"]').type('');

    cy.get('[data-testid="continue"]').click();

    cy.get('[data-testid="error"]').should('be.visible');
    cy.get('[data-testid="error"]').should('contain', 'First Name is required');
  });

  it('should display error when both firstName and lastName are empty', () => {
    cy.get('[data-testid="add-to-cart-sauce-labs-backpack"]').click();
    cy.get('[data-testid="shopping_cart_link"]').click();
    cy.get('[data-testid="checkout"]').click();

    cy.get('[data-testid="firstName"]').should('be.visible');
    cy.get('[data-testid="firstName"]').type('');

    cy.get('[data-testid="lastName"]').should('be.visible');
    cy.get('[data-testid="lastName"]').type('');

    cy.get('[data-testid="continue"]').click();

    cy.get('[data-testid="error"]').should('be.visible');
    cy.get('[data-testid="error"]').should('contain', 'First Name and Last Name are required');
  });
});
